with unpacked as (select id, created_at, coupon_codes, items, ship_to, attributes, size(filter(items, x -> x.qty >= 3)) as bulk_lines, coalesce(attributes['utm_source'], 'none') as utm_source_or_default, ship_to.country as ship_country from carts) select id, bulk_lines, utm_source_or_default, count(bulk_lines) over (partition by ship_country order by cast(created_at as bigint) asc range between 1800 preceding and current row) as bulk_lines_count_30m, avg(bulk_lines) over w_part as bulk_lines_avg_5 from unpacked window w_part as (partition by month(created_at), ship_country order by bulk_lines asc, id asc rows between 5 preceding and current row);
